/**
 * Universal links (iOS) / App Links (Android) for snapshot-x.nl: with the app installed, a scanned QR or shared
 * https://snapshot-x.nl/add/<username> link opens the app on the add-friend screen instead of the website.
 * Pure (no React Native imports) so the web export script and node tests can use it.
 *
 * The site must serve two files, generated by `npm run web:real` when the env has the values (never guessed):
 *   /.well-known/apple-app-site-association   needs SNAPSHOTX_APPLE_TEAM_ID (Kevin's own Apple team, 10 chars)
 *   /.well-known/assetlinks.json              always lists the EAS upload key below; SNAPSHOTX_ANDROID_SHA256 adds the
 *                                             Play app-signing certificate (known after the first Play upload)
 */
export const APP_BUNDLE_ID = 'com.snapshotx.app';
export const ANDROID_PACKAGE = 'com.snapshotx.app';
export const LINK_HOSTS = ['snapshot-x.nl', 'www.snapshot-x.nl'] as const;
/** Android verified App Links: apex only. www.snapshot-x.nl answers with a 308 redirect, and Android's verifier does not
 *  follow redirects for /.well-known/assetlinks.json; on Android ≤ 11 one failing host fails the whole filter. All QR and
 *  share links use the apex host (lib/friend-code.ts). */
export const ANDROID_LINK_HOSTS = ['snapshot-x.nl'] as const;
/** Paths that open in the app. Everything else (privacy, help, terms, web chat) stays on the website. */
export const APP_LINK_PATHS = ['/add/*'] as const;

/**
 * SHA-256 of the EAS Android upload keystore for com.snapshotx.app (build credentials "cE8pK-ijik", JKS, read-only via
 * `eas credentials -p android` on 1 Nov 2026). A certificate fingerprint is public (it is in every signed APK), not a secret.
 * Builds signed with this key (EAS internal/preview APKs) verify App Links now; Google Play re-signs store installs with its
 * own app-signing key, which must be added via SNAPSHOTX_ANDROID_SHA256 once the Play Console shows it.
 */
export const EAS_UPLOAD_KEY_SHA256 = '79:28:8D:38:93:69:45:68:9A:27:1D:A9:F6:F7:7C:50:CD:68:41:D0:A3:F9:23:FF:90:BF:5E:DE:E2:D5:53:82';

const TEAM_RE = /^[A-Z0-9]{10}$/;
const SHA_RE = /^([0-9A-F]{2}:){31}[0-9A-F]{2}$/;

export function isTeamId(v: string | undefined): v is string { return !!v && TEAM_RE.test(v); }

/** Accepts "AA:BB:…" or plain 64 hex chars (any case) → canonical "AA:BB:…"; null when not a SHA-256 fingerprint. */
export function normalizeSha256(v: string | undefined): string | null {
  const raw = (v ?? '').trim().toUpperCase();
  if (SHA_RE.test(raw)) return raw;
  if (/^[0-9A-F]{64}$/.test(raw)) return raw.match(/../g)!.join(':');
  return null;
}

/** apple-app-site-association: modern `components` plus legacy `paths` (iOS 12) for the same app id. */
export function appleAppSiteAssociation(teamId: string, bundleId = APP_BUNDLE_ID) {
  if (!isTeamId(teamId)) throw new Error('Ongeldige Apple Team ID (10 hoofdletters/cijfers).');
  const appID = `${teamId}.${bundleId}`;
  return {
    applinks: {
      apps: [] as string[],
      details: [{ appIDs: [appID], appID, paths: [...APP_LINK_PATHS], components: APP_LINK_PATHS.map(p => ({ '/': p, comment: 'Vriend toevoegen via QR/link' })) }],
    },
  };
}

/** Digital Asset Links for Android App Links. */
export function androidAssetLinks(fingerprints: string[], pkg = ANDROID_PACKAGE) {
  const fps = fingerprints.map(normalizeSha256);
  if (!fps.length || fps.some(f => !f)) throw new Error('Ongeldige SHA-256-vingerafdruk voor Android.');
  return [{ relation: ['delegate_permission/common.handle_all_urls'], target: { namespace: 'android_app', package_name: pkg, sha256_cert_fingerprints: fps as string[] } }];
}

export type WellKnownFile = { path: string; json: unknown };
/** Files to write into the web export, plus Dutch notes for what was skipped (missing/invalid env). */
export function wellKnownFiles(env: Record<string, string | undefined>): { files: WellKnownFile[]; notes: string[] } {
  const files: WellKnownFile[] = [], notes: string[] = [];
  const team = env.SNAPSHOTX_APPLE_TEAM_ID?.trim();
  if (!team) notes.push('Geen SNAPSHOTX_APPLE_TEAM_ID: apple-app-site-association overgeslagen (iOS-links openen de website).');
  else if (!isTeamId(team)) notes.push('SNAPSHOTX_APPLE_TEAM_ID is ongeldig (10 hoofdletters/cijfers): apple-app-site-association overgeslagen.');
  else files.push({ path: '.well-known/apple-app-site-association', json: appleAppSiteAssociation(team) });
  const shaRaw = env.SNAPSHOTX_ANDROID_SHA256?.trim();
  const fps: string[] = [EAS_UPLOAD_KEY_SHA256];
  if (!shaRaw) notes.push('Geen SNAPSHOTX_ANDROID_SHA256: assetlinks.json bevat alleen de EAS-uploadsleutel (Play-app-ondertekeningssleutel nog toevoegen).');
  else {
    const list = shaRaw.split(/[\s,]+/).filter(Boolean);
    if (list.some(f => !normalizeSha256(f))) notes.push('SNAPSHOTX_ANDROID_SHA256 is ongeldig: assetlinks.json bevat alleen de EAS-uploadsleutel.');
    else for (const f of list.map(x => normalizeSha256(x)!)) if (!fps.includes(f)) fps.push(f);
  }
  files.push({ path: '.well-known/assetlinks.json', json: androidAssetLinks(fps) });
  return { files, notes };
}

/** Native config: iOS associated domains (only when opted in) and Android verified intent filters for /add. */
export function iosAssociatedDomains(): string[] { return LINK_HOSTS.map(h => `applinks:${h}`); }
export function androidIntentFilters() {
  return [{ action: 'VIEW', autoVerify: true, data: ANDROID_LINK_HOSTS.map(host => ({ scheme: 'https', host, pathPrefix: '/add/' })), category: ['BROWSABLE', 'DEFAULT'] }];
}
